module.exports=[82193,a=>{"use strict";let b=[{slug:"offline-first-clinical-decision-support",name:"Offline-First Clinical Decision Support Platform",oneLiner:"A multi-agent AI system that gives rural health workers real-time clinical guidance with no internet connection.",role:"Agentic Systems Backend Engineer",org:"HabTech Solution — Ethiopia Health Extension Program",period:"Feb 2026 – Aug 2026",status:"In Production",categories:["AI / ML","Backend / Systems","Client Work"],featured:!0,stack:["Python","FastAPI","LangGraph","PostgreSQL","Redis","Celery","Offline-first sync","Rule-based validation layer"],metrics:[{label:"Health workers served",value:"~5,000"},{label:"Response latency",value:"< 5s, offline"},{label:"Unsafe recommendations prevented",value:"~98%"},{label:"Data loss risk reduced",value:"~90%"},{label:"Query resolution time reduced",value:"~35%"}],links:{demo:void 0,repo:void 0},architecture:[{label:"Field device (offline-capable client)",detail:"Runs fully without a network connection — a health worker can query it mid-consultation with zero signal."},{label:"Local sync & queue layer",detail:"Queues requests and results locally, then reconciles with the backend the moment connectivity returns, without losing data."},{label:"Intent router (multi-agent: consultation / simulation / analysis)",detail:"Classifies what the worker is actually asking and hands it to one narrow agent instead of a single expensive general-purpose call."},{label:"Guideline-grounded knowledge layer",detail:"Anchors every model output to approved national medical guidelines rather than open-ended generation."},{label:"Deterministic safety validation rules",detail:"Re-checks AI output against hard rules for vaccine schedules, dosage, and danger signs before it reaches a worker."},{label:"National health data pipeline",detail:"Aggregates inputs from thousands of distributed field devices into a single real-time view."},{label:"Policymaker analytics interface",detail:"Lets non-technical stakeholders ask questions in plain language and get a context-aware visualisation back."}],sections:{overview:"A national-scale platform that lets health workers in low-connectivity regions get AI-assisted clinical guidance, while giving federal and regional stakeholders a live view of immunization and maternal-health indicators.",problem:"Ethiopia's Health Extension Program relies on thousands of rural workers who often operate with no reliable internet access. Existing decision-support tools assumed connectivity, leaving frontline workers without guidance exactly when it mattered — and left policymakers unable to see what was happening on the ground in anything close to real time.",solution:"I architected an offline-first platform where the client keeps working without a network, and a multi-agent backend intelligently routes each worker's question to the right specialised agent — consultation, simulation, or analysis — rather than sending every request through a single expensive model call. Every AI-generated recommendation is checked against a deterministic rules layer for things like vaccine schedules, dosage, and danger-sign detection before it ever reaches a worker, and outputs are grounded in approved national medical guidelines rather than open-ended generation.",role:"I designed the multi-agent routing system, the guideline-grounding layer that anchors model outputs to approved clinical protocols, the safety-validation rules engine, and the fault-tolerant sync architecture that lets field devices operate through intermittent connectivity without losing data. I also built the aggregation pipeline and natural-language analytics interface that non-technical policymakers use to query health data directly.",challenges:[{heading:"Trustworthy AI under clinical stakes",body:["A hallucinated recommendation in this context isn't a bad UX moment, it's a patient-safety risk. I addressed this by treating the LLM as one input to a decision, not the decision-maker: outputs are grounded against approved guidelines and then re-checked by deterministic rules before anything reaches a health worker. That combination is what got unsafe recommendations down to roughly 2%, rather than trying to solve safety with prompting alone."]},{heading:"Designing for intermittent, not absent, connectivity",body:["The hard case isn't 'always offline' or 'always online' — it's a device that drops and regains connectivity unpredictably mid-session. I built fault-tolerant sync workflows around this reality specifically, which is what took data-loss risk down by roughly 90% instead of just handling the easy fully-offline case."]},{heading:"Keeping routing cheap at national scale",body:["Sending every query to a full model call doesn't scale to thousands of concurrent field devices. The multi-agent router classifies intent first and only invokes the specialised agent actually needed, which is what reduced both query resolution time and unnecessary model usage together, rather than trading one for the other."]}],decisions:[{heading:"A rules layer instead of relying on the model alone",body:["For dosage and danger-sign logic specifically, deterministic rules are auditable and testable in a way a model's reasoning isn't. I kept the LLM responsible for language and triage, and kept anything with a hard clinical threshold in explicit, versioned rules."]},{heading:"Multiple narrow agents instead of one general agent",body:["A single general-purpose agent would have made every query pay the cost — and the risk profile — of the hardest query type. Splitting consultation, simulation, and analysis into separate agents with a lightweight router in front kept each agent's scope, and its failure modes, easier to reason about."]}],results:["~5,000 rural health workers now get clinical guidance with response latency under 5 seconds even without connectivity.","~98% of unsafe recommendations are caught before reaching a health worker.","~90% reduction in data-loss risk across intermittent-connectivity field deployments.","~35% reduction in query resolution time via intelligent agent routing.","Regional and federal stakeholders can now query immunization and maternal-health data in natural language and get a visualisation back in seconds."]}},{slug:"self-initiated-ai-platform",name:"Real-Time RAG Platform with Hybrid Retrieval",oneLiner:"A self-initiated, end-to-end AI platform combining live web ingestion, hybrid retrieval, and a real-time WebSocket layer across three client apps.",role:"Full-Stack & AI Engineer",org:"Self-Initiated Project",period:"Aug 2024 – Jan 2025",status:"Completed",categories:["AI / ML","Full-Stack","Backend / Systems"],featured:!0,stack:["FastAPI","Async PostgreSQL","Redis","Celery","LangGraph","Qdrant","Neo4j","Next.js","Flutter","Docker"],metrics:[{label:"Knowledge staleness reduced",value:"> 80%"},{label:"Concurrent requests",value:"500+"},{label:"Uptime",value:"~99.9%"},{label:"Median API latency",value:"< 200ms"},{label:"Interaction latency cut",value:"~45%"},{label:"Retrieval precision gain",value:"~28%"},{label:"Duplicate frontend logic cut",value:"~60%"},{label:"Cold-start deploy time",value:"12min → <3min"}],links:{demo:void 0,repo:void 0},architecture:[{label:"Clients (Next.js web, Flutter mobile, admin dashboard)",detail:"Three surfaces, zero duplicated business logic — everything calls the same API."},{label:"Single shared API layer (FastAPI)",detail:"The one place domain logic lives, so every client stays in sync by construction."},{label:"LangGraph agentic workflow layer",detail:"Orchestrates multi-step reasoning instead of a single prompt-in, answer-out call."},{label:"Hybrid retrieval: Qdrant (semantic) + Neo4j (graph reasoning)",detail:"Vector search for similarity, graph traversal for relational questions vectors can't answer well."},{label:"Live web-ingestion / NLP pipeline",detail:"Keeps the knowledge base current from live sources instead of a static, aging corpus."},{label:"Async PostgreSQL + Redis + Celery",detail:"Handles 500+ concurrent requests at sub-200ms median latency without over-provisioning."},{label:"Docker / Gunicorn deployment on Hugging Face Spaces",detail:"Reproducible builds that cut cold-start deploy time from ~12 minutes to under 3."}],sections:{overview:"A personal project built to explore what a genuinely real-time, always-current RAG system looks like once you stop assuming a static knowledge base — spanning a shared backend, two frontend clients, and an admin dashboard.",problem:"Most RAG demos retrieve from a fixed, pre-indexed corpus that goes stale the moment the world changes. I wanted to know what it would take to keep a knowledge base continuously current from live web sources, and to make retrieval itself smarter than a single vector-similarity lookup.",solution:"I built LangGraph-based agentic workflows paired with live web-scraping NLP pipelines so the knowledge base updates continuously instead of going stale, and combined Qdrant semantic search with Neo4j graph reasoning so structured, relational queries aren't limited to vector-similarity alone. A real-time WebSocket layer with async processing keeps multiple clients in sync during a session, and all three clients — Next.js web, Flutter mobile, and an admin dashboard — share one API layer rather than duplicating logic per platform.",role:"I designed and built the full system end-to-end: the FastAPI backend, the hybrid retrieval layer, the LangGraph agent workflows, the WebSocket real-time layer, all three client applications, and the deployment pipeline.",challenges:[{heading:"Retrieval quality beyond vector similarity",body:["Pure vector search struggles with structured, relational questions — 'what depends on what' isn't really a similarity problem. Pairing Qdrant with a Neo4j graph layer for relational reasoning is what pushed retrieval precision up by roughly 28% on that class of query specifically, without regressing plain semantic lookups."]},{heading:"Real-time state across concurrent sessions",body:["Keeping multiple clients — web, mobile, and an admin view — in sync during a live session meant the WebSocket layer had to do more than push messages; it had to reconcile state across async workers. Building that on top of async processing is what cut end-user interaction latency by roughly 45%."]},{heading:"One API, three very different clients",body:["Flutter, Next.js, and an internal dashboard have different rendering models and lifecycles. Rather than let each client grow its own copy of the business logic, I kept that logic entirely in the shared API layer, which is what cut duplicate frontend logic by roughly 60% and kept feature parity manageable across platforms."]}],decisions:[{heading:"Hybrid retrieval instead of vector-only",body:["Vector search alone is a strong default, but it isn't the right primitive for relational questions. Adding a graph layer rather than trying to force everything through embeddings kept each retrieval mode doing the job it's actually good at."]},{heading:"Async stack over a simpler sync one",body:["500+ concurrent requests with sub-200ms median latency isn't realistic on a synchronous stack without heavy over-provisioning. Async PostgreSQL, Redis, and Celery let the system handle load spikes without the infrastructure cost of just throwing more sync workers at the problem."]}],results:["Reduced knowledge staleness by over 80% versus a static corpus, via continuous live-web ingestion.","500+ concurrent requests handled at ~99.9% uptime with sub-200ms median API response time.","~28% improvement in retrieval precision on structured relational queries versus vector-only baselines.","~45% cut in end-user interaction latency from the async WebSocket layer.","~60% reduction in duplicate frontend logic by sharing one API layer across three clients.","Cold-start deployment time cut from ~12 minutes to under 3 minutes."]}},{slug:"salvation-day",name:"Salvation Day",oneLiner:"A full-stack AI platform for a client, combining scalable APIs, async processing, and AI-powered content workflows — live and in ongoing deployment.",role:"Full-Stack & AI Engineer",org:"Client Project (via Upwork) — Salvation Day",period:"2026 · ongoing deployment",status:"In Production",categories:["AI / ML","Full-Stack","Client Work"],featured:!0,stack:["Next.js","FastAPI","Celery","Redis","PostgreSQL","LangGraph","Docker"],metrics:[],links:{demo:"https://salvation-day.vercel.app/en"},architecture:[{label:"Client (Next.js)",detail:"The user-facing surface, served from the same deployment as the API."},{label:"API layer (FastAPI)",detail:"Scalable REST endpoints fronting the application logic."},{label:"Async workers (Celery + Redis)",detail:"Background processing so long-running work never blocks a request."},{label:"AI content workflows (LangGraph)",detail:"Orchestrates the AI-powered content generation/processing steps."},{label:"Real-time layer (WebSockets)",detail:"Pushes live updates to connected clients as background work completes."},{label:"Data layer (PostgreSQL + Redis)",detail:"Persistent storage plus a fast cache/queue backing the async layer."},{label:"Dockerized deployment",detail:"Reproducible builds shipped as containers."}],sections:{overview:"A full-stack AI platform built and delivered for a client, now live and in ongoing deployment. It combines scalable REST APIs, async background processing, real-time communication, and AI-powered content workflows in a single modular codebase.",problem:"[Add the specific client problem and goals this platform addresses]",solution:"I built the system around a clean, modular architecture: a Next.js frontend, a FastAPI backend exposing scalable REST APIs, Celery and Redis handling async background processing, a WebSocket layer for real-time communication, and LangGraph orchestrating the AI-powered content workflows at the core of the product. The whole system ships as Docker containers.",role:"I designed and delivered the platform end-to-end — architecture, backend APIs, async processing pipeline, real-time layer, AI workflow orchestration, and the deployment setup.",challenges:[{heading:"Keeping AI workflows from blocking the request path",body:["AI-powered content generation is inherently slow and variable in latency. Routing that work through Celery/Redis background workers, with WebSockets pushing the result back once ready, kept the API responsive regardless of how long a given workflow takes."]},{heading:"Modularity under a real delivery timeline",body:["Client work has to stay maintainable past handoff. Keeping the architecture clean and modular — clear boundaries between the API, the async layer, and the AI workflow layer — was a deliberate choice to keep the system extensible after delivery, not just to ship the first version."]}],decisions:[{heading:"Celery + Redis for the AI workflow queue",body:["AI content workflows don't fit a synchronous request/response model. A dedicated async queue let the API stay fast while the actual generation work happens in the background."]}],results:["Shipped to production and in ongoing live deployment.","[Add measurable results if available]"]}},{slug:"spotter-labs-fuel-optimization",name:"Fuel-Optimized Route Planning API",oneLiner:"A Django REST backend that plans cost-optimal fuel stops along a route using graph-based shortest-path search and spatial indexing.",role:"Backend Developer",org:"Spotter Labs — prototype",period:"Feb 2026",status:"Completed",categories:["Backend / Systems","Client Work"],featured:!0,stack:["Django","PostgreSQL","Redis"],metrics:[],links:{demo:"https://plan-trip-sage.vercel.app/"},architecture:[{label:"Client (plan-trip-sage.vercel.app)",detail:"The front end that submits a trip and displays the recommended route and fuel stops."},{label:"REST API (Django REST Framework)",detail:"A production-grade API layer built with Clean Architecture principles for testable, maintainable code."},{label:"Fuel optimization engine (Dijkstra)",detail:"Models the route as a graph and finds the shortest-cost path while respecting vehicle range and MPG."},{label:"Spatial indexing (H3 + bounding-box filtering)",detail:"Narrows down fuel-station candidates efficiently instead of scanning every station along the route."},{label:"Routing & caching layer",detail:"Single-call routing that returns route polylines, per-mile fuel spend, and stop recommendations together; built cache-ready."},{label:"Data layer (PostgreSQL/PostGIS-ready + Redis)",detail:"Bulk queries and a PostGIS-ready schema, with Redis caching for scalable performance."}],sections:{overview:"A backend prototype for trip fuel planning: given a route and a vehicle's range and MPG, it recommends the fuel stops that minimize total trip fuel cost.",problem:"Picking cost-efficient fuel stops along a long route isn't a simple nearest-station lookup — it has to account for the vehicle's range and MPG and the total cost across the whole trip, without exhaustively checking every station along the way.",solution:"I modeled the route as a graph and used a Dijkstra-based shortest-path algorithm to find the minimum-cost sequence of fuel stops within the vehicle's range. Fuel-station retrieval uses H3 spatial indexing with bounding-box filtering to keep candidate lookups fast, and the API returns route polylines, per-mile fuel spend, and stop recommendations from a single call, built on a caching-ready architecture with PostgreSQL/PostGIS-ready data modeling and Redis.",role:"I designed and built the backend end-to-end: the Clean Architecture REST API, the Dijkstra-based optimization engine, the H3 spatial indexing layer, and the caching-ready data layer.",challenges:[{heading:"Modeling fuel stops as a shortest-path problem",body:["Minimizing total trip cost isn't the same as minimizing distance or number of stops. Representing candidate fuel stations and route segments as a graph let a standard Dijkstra search do the actual optimization, instead of hand-rolling heuristics."]},{heading:"Keeping station lookups fast along a long route",body:["Checking every fuel station against every route segment doesn't scale. H3 spatial indexing combined with bounding-box filtering narrows the candidate set before the optimization step ever runs, which is what keeps route computation fast."]}],decisions:[{heading:"Clean Architecture on Django REST Framework",body:["For a backend meant to be handed off or extended, keeping the domain logic (the optimization engine) separate from the framework and infrastructure layers made the code testable independent of Django itself."]},{heading:"H3 over naive geo-radius queries",body:["A naive radius query against every station gets slower as the station dataset grows. H3's hexagonal indexing gives constant-ish lookup behavior that scales better with data size."]}],results:["Delivered a working single-call routing flow: route polyline, per-mile fuel spend, and fuel-stop recommendations in one response.","Reduced fuel-station query complexity via H3 spatial indexing and bounding-box filtering.","[Add measurable results if available]"]}},{slug:"hew-ai-echis",name:"HEW-AI — eCHIS Research Project",oneLiner:"An ongoing research project delivering an AI-assisted mobile app and backend platform that trains and supports Health Extension Workers in the field.",role:"Full-Stack & AI Engineer",org:"Research Project — HEW-AI / eCHIS",period:"2026 · ongoing research",status:"Research Prototype",categories:["Experimental / Research","AI / ML","Full-Stack"],featured:!0,stack:["LLMs","AI/decision support","Mobile application","Backend platform","Offline-first / edge design"],metrics:[],links:{},architecture:[{label:"Mobile application (Health Extension Workers)",detail:"The field-facing surface Health Extension Workers use day to day, built with production availability in mind rather than as a research demo."},{label:"AI / LLM decision-support layer",detail:"Provides healthcare-focused guidance grounded in the local context the research identified, rather than generic model output."},{label:"Backend platform",detail:"A substantial backend behind the mobile app, handling the data and logic the decision-support layer depends on."},{label:"Offline/edge-aware design",detail:"Designed with scalability and intermittent connectivity in mind, for real-world deployment in the field."}],sections:{overview:"A research-based project to train and manage Health Extension Workers in their local context, addressing a problem identified through the research itself. It pairs a mobile application with a substantial backend platform, and a production build of the mobile app is now available.",problem:"Health Extension Workers need context-specific training and management support that generic tooling doesn't provide — the research behind this project set out to identify that gap directly rather than assume it.",solution:"I'm building an AI/LLM-assisted mobile application, backed by a substantial backend platform, that gives Health Extension Workers decision support grounded in their local context. The system is being designed with scalability, offline/edge capability, and real-world field deployment in mind, and a production version of the mobile app is already available.",role:"I'm building the mobile application and the backend platform behind it, including the AI/LLM-driven decision-support layer and the offline/edge-aware architecture needed for real field conditions.",challenges:[],decisions:[],results:["Production build of the mobile application is now available.","Ongoing research and development — backend platform and decision-support layer continuing to evolve."]}},{slug:"grammar-guided-generative-programming",name:"Grammar-Guided Generative Programming Research",oneLiner:"Experimental pipelines combining evolutionary algorithms with subgraph mining to push structured text generation past conventional neural architectures.",role:"Research Intern — Generative AI Systems",org:"iCog Labs (NAC Team)",period:"Nov 2025 – Jan 2026",status:"Research Prototype",categories:["Experimental / Research","AI / ML"],featured:!0,stack:["Transformer architectures","Evolutionary algorithms","Subgraph mining","Benchmarking pipelines"],metrics:[{label:"Constraint adherence improvement",value:"~25%"},{label:"Experiment iteration time reduced",value:"~30%"}],links:{demo:void 0,repo:void 0},architecture:[{label:"Grammar specification",detail:"Defines the hard structural constraints generation must respect."},{label:"Evolutionary search over candidate programs",detail:"Explores the constrained output space instead of relying on decoding alone."},{label:"Subgraph mining for structural reuse",detail:"Finds reusable structural patterns across candidates to guide the search."},{label:"Transformer-based generation",detail:"Produces candidate outputs within the grammar's constraints."},{label:"Benchmarking & feasibility reporting",detail:"Evaluates accuracy, complexity, and scalability together to inform downstream teams."}],sections:{overview:"A research engagement exploring generative programming systems that go beyond standard transformer decoding, by constraining generation with grammars and using evolutionary search and subgraph mining to explore the structured-output space.",problem:"Conventional neural text generation is weak at reliably respecting hard structural constraints. The NAC team wanted to know whether combining evolutionary algorithms and subgraph mining with grammar-guided generation could meaningfully improve constraint adherence, and whether the approach was practical enough to inform two downstream engineering teams' roadmaps.",solution:"I built experimental grammar-guided generative programming pipelines that combined evolutionary algorithms with subgraph mining, extending structured text generation beyond what conventional neural architectures do on their own. I then evaluated the prototypes across accuracy, computational complexity, and scalability, and wrote up feasibility reports for the teams deciding whether to build on the approach.",role:"I designed the experimental pipelines, ran the benchmarking across multiple dimensions, and built reproducible experimentation and validation workflows the wider research team could reuse.",challenges:[{heading:"Benchmarking a genuinely new approach fairly",body:["There wasn't an established benchmark for grammar-guided generation combined with evolutionary search, so I evaluated across accuracy, computational complexity, and scalability together rather than optimizing for a single metric that would have hidden trade-offs."]},{heading:"Making iteration fast enough to actually explore the space",body:["Evolutionary search is iteration-hungry. I designed reproducible experimentation and validation pipelines specifically to cut iteration time, which is what brought experiment turnaround down by roughly 30% and made broader hypothesis testing practical within the research timeline."]}],decisions:[{heading:"Reproducibility infrastructure before scaling experiments",body:["It would have been faster short-term to run one-off scripts per experiment. I built the reproducible pipeline first because the team was going to run many variations, and that upfront investment is what paid off in the ~30% iteration-time reduction."]}],results:["~25% improvement in output constraint adherence versus conventional neural generation baselines.","~30% reduction in experimental iteration time via reproducible pipelines.","Feasibility reports directly influenced project prioritisation for two downstream engineering teams."]}}];a.s(["blogHighlights",0,[],"contact",0,{email:"sisaytadewos@gmail.com",phone:"0954788355",linkedin:"https://www.linkedin.com/in/sisay-tadewos-790228275",githubUsername:"Sisyetad",upwork:"https://www.upwork.com/freelancers/~01636e3fbdb485547f",location:"Addis Ababa, Ethiopia"},"education",0,[{degree:"B.Sc. Software Engineering",org:"Addis Ababa University (AAIT)",period:"2027",detail:"Mathematics & Computational Science · GPA 3.82 / 4.0"},{degree:"B.Sc. Computer Science",org:"African to Silicon Valley (A2SV)",period:"2026",detail:void 0}],"experience",0,[{role:"Agentic Systems Backend Engineer",org:"HabTech Solution",period:"Feb 2026 – Aug 2026",location:"Addis Ababa, Ethiopia",summary:"Architected a national-scale, offline-first AI platform for Ethiopia's Health Extension Program, combining multi-agent routing, guideline-grounded outputs, and a deterministic safety layer.",focus:["Multi-agent systems","Offline-first architecture","AI safety & validation","Data pipelines"],projectSlug:"offline-first-clinical-decision-support"},{role:"Research Intern — Generative AI Systems",org:"iCog Labs (NAC Team)",period:"Nov 2025 – Jan 2026",location:"Addis Ababa, Ethiopia",summary:"Built and benchmarked grammar-guided generative programming pipelines combining evolutionary algorithms with subgraph mining, informing engineering roadmap decisions for two teams.",focus:["Generative AI research","Benchmarking","Experimental design"],projectSlug:"grammar-guided-generative-programming"},{role:"Full-Stack & AI Engineer",org:"Self-Initiated Project",period:"Aug 2024 – Jan 2025",location:"Addis Ababa, Ethiopia",summary:"Designed and delivered an end-to-end AI platform: LangGraph agents, hybrid Qdrant + Neo4j retrieval, a real-time WebSocket layer, and three client applications on one shared API.",focus:["RAG systems","Real-time systems","Full-stack delivery"],projectSlug:"self-initiated-ai-platform"},{role:"Backend Developer",org:"Spotter Labs",period:"February 2026 – February 2026",location:"Remote",summary:"Built a production-grade Django REST API prototype/MVP for fuel-optimized route planning, using Clean Architecture, a Dijkstra-based optimization engine, and H3 spatial indexing for fast fuel-station retrieval.",focus:["Clean Architecture","Graph algorithms","Spatial indexing","Django REST Framework"],projectSlug:"spotter-labs-fuel-optimization"}],"philosophy",0,[{title:"Build from the problem, not the technology",body:"The offline-first platform started from '5,000 health workers have no reliable internet,' not from a stack. The stack followed from there."},{title:"Treat AI as a system, not an API call",body:"A model call is one component. Grounding, validation, and routing around it are what make an AI feature something you can actually trust in production."},{title:"Prefer simple architectures until complexity is justified",body:"Multi-agent routing earned its place because a single general agent was measurably slower and more expensive. It wasn't the starting point."},{title:"Separate domain logic from infrastructure",body:"Clean boundaries between what the system does and what it runs on are what let new AI capabilities ship into a live national deployment without service disruption."},{title:"Design for reliability before scale",body:"Fault-tolerant sync for intermittent connectivity mattered more than raw throughput — the failure mode that actually occurs in the field is the one worth engineering for first."}],"profileImageUrl",0,"https://res.cloudinary.com/dxwakqqlg/image/upload/v1788796751/salvation_day/testimonies/photo_2026-06-19_18-44-13_90387b8b.jpg","projects",0,b,"stack",0,[{group:"Languages",items:["Python","TypeScript","JavaScript","Dart"]},{group:"AI Systems & Machine Learning",items:["LLMs","RAG pipelines","Multi-agent orchestration","LangChain","LangGraph","NLP","Transformer architectures","On-device inference","PyTorch","TensorFlow","Scikit-learn"]},{group:"Backend & Distributed Systems",items:["Django","FastAPI","REST APIs","WebSockets / SSE","Async processing","Celery","Event-driven design","Fault-tolerant systems","Microservices"]},{group:"Data & Storage",items:["PostgreSQL","MySQL","Redis","Neo4j","Qdrant (vector search)","Hybrid retrieval systems","Real-time data pipelines"]},{group:"Frontend & Cross-Platform",items:["React","Next.js","Flutter"]},{group:"Architecture & Design",items:["Clean Architecture","Domain-Driven Design","CQRS","Strategy / Factory / Observer patterns","Dependency injection","Offline-first system design"]},{group:"Infrastructure",items:["Docker","CI/CD","Linux","Git"]}],"telegramChannel",0,{handle:"[add_telegram_channel_username]",displayName:"@[add_telegram_channel_username]"}])}];

